function migrateSource(saved){ return {...saved,sourceVersion:SOURCE_VERSION}; }
let db=fresh,loadError='';try{const saved=localStorage.getItem(KEY);if(saved)db=migrateSource(validate(JSON.parse(saved)))}catch(e){loadError='Os dados locais não puderam ser carregados. Abra um backup para recuperar.'}
