function records({ignoreStatus=false}={}){return projects().flatMap(p=>{const latest=sortedWeeks(p).at(-1)?.id;return p.tasks.filter(t=>{const w=p.weeks.find(w=>w.id===t.weekId),a=assignment(p,t);return(state.period==='all'||state.period==='latest'&&w.id===latest||w.start===state.period)&&(state.sector==='all'||norm(t.sector)===state.sector)&&(state.person==='all'||state.person==='unassigned'&&!a.people.length||a.people.includes(state.person))&&(!state.q||norm(t.name+' '+t.sector+' '+p.name+' '+names(a).join(' ')+' '+(a.note||'')+' '+(a.teamName||'')).includes(norm(state.q)))&&(ignoreStatus||state.status==='all'||statusCode(p,t)===state.status)}).map(t=>({p,t,w:p.weeks.find(w=>w.id===t.weekId)}))})}
